import csv

rows = []
with open('contacts.csv', newline='', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for idx, row in enumerate(reader):
        email = row['email'].strip().lower()
        created = row['created'].strip()
        rows.append((idx, row['name'], email, created))

best = {}
for idx, name, email, created in rows:
    if email not in best:
        best[email] = (created, idx, name, email)
    else:
        cur = best[email]
        if (created, idx) < (cur[0], cur[1]):
            best[email] = (created, idx, name, email)

result = sorted(best.values(), key=lambda x: (x[0], x[3]))
with open('clean.csv', 'w', newline='', encoding='utf-8') as f:
    writer = csv.writer(f, lineterminator='\n')
    writer.writerow(['name', 'email', 'created'])
    for created, idx, name, email in result:
        writer.writerow([name, email, created])
